INSERT INTO products (id, Createdate, image, name, price, categoryid, number, available, description) VALUES
(30, '2026-07-18', 'bia1.jpg', 'Bia Laru - Vui cùng miền trung nào', 21.99, 'B', 250, 1, '- Bia Larue là sự hoà quyện tinh tế mang đậm hương vị đặc trưng của hơn 100 năm truyền thống bia Pháp. - Sản phẩm được sản xuất với thành phần tự nhiên, trên dây chuyền công nghệ hiện đại và lên men theo công nghệ truyền thống dài ngày, tạo nên một hương vị ngon và độc đáo khác hẳn với các sản phẩm bia khác trên thị trường. Bia Larue có màu vàng sậm bắt mắt, mùi thơm đặc trưng, hương vị đậm đà, mang lại những trải nghiệm thú vị cho người thưởng thức. - Sản phẩm với thiết kế kiểu dáng lon nhỏ gọn, vừa tay cầm, tiện lợi khi dùng và dễ dàng bảo quản. Bia Larue thùng 24 lon x 330ml có thể dùng trong những dịp họp mặt bạn bè, cuộc gặp với đối tác kinh doanh hay đơn giản là người bạn thân thiết trong mỗi bữa ăn gia đình. Sản phẩm mang đến không khí vui vẻ trọn vẹn trong mọi cuộc vui.'),
(31, '2026-09-05', 'bia2.jpg', 'Bia Oranjeboom Premium Strong', 22.99, 'B', 106, 1, 'Mại dô mại dô nào Thuộc dòng bia lager đầy sảng khoái, đem đến trải nghiệm khá tuyệt vời cho người uống. Mùi vị của những lon bia Oranjeboom này được đánh giá là điểm nhấn đầy hấp dẫn và thú vị với người dùng. Bia hấp dẫn, với vị bia thanh mát được làm chủ yếu từ lúa mạch – hoa bia – malt cháy và nước tinh khiết. Vị bia thơm ngon, đầy thu hút và ấn tượng, đem đến điểm nhấn lôi cuốn người dùng. Và đặc biệt hơn, với độ cồn 16% sẽ chinh phục những quý ông yêu thích khám phá các loại bia nặng độ. Oranjeboom khá thú vị, mang đến trải nghiệm tuyệt vời hơn hẳn.'),
(32, '2026-07-07', 'bia3.jpg', 'Bia X-Mark Tequila 5,9% – Lon 500ml – Thùng 12 lon', 24.99, 'B', 60, 1, 'Bia X-Mark Tequila 5,9% – Lon 500ml – Thùng 12 lon được ủ theo công nghệ lên men truyền thống, vị đậm đà và hậu vị êm. Ngon nhất khi uống lạnh ở 6–8°C, thích hợp cho tiệc tùng, họp mặt bạn bè và gia đình.'),
(33, '2026-03-26', 'bia4.jpg', 'Bia Heineken Pháp 5% – Chai 250ml – Thùng 20 chai', 18.99, 'B', 33, 1, 'Heineken Lager hay bia Heineken, là một loại bia nhạt với nồng độ cồn 5% và có nguồn gốc từ công ty sản xuất bia ở Amsterdam, Hà Lan, do Gerard Adriaan Heineken thành lập vào năm 1864. Đến 2012, Heineken đã sở hữu gần 190 nhà máy sản xuất bia ở hơn 70 đất nước khác nhau và hiện là thương hiệu sản xuất bia lớn thứ 3 thế giới. Năm 1990, nhà máy HEINEKEN Việt Nam, trực thuộc tập đoàn HEINEKEN ở Hà Lan được thành lập. Tính đến nay, HEINEKEN Việt Nam đã và đang điều hành 6 nhà máy ở Hà Nội, Quảng Nam, Đà Nẵng, Vũng Tàu, thành phố Hồ Chí Minh, Tiền Giang và được xếp làm nhà sản xuất bia lớn thứ 2 trong nước. Với công nghệ tiên tiến hiện đại cùng công thức sản xuất bia độc quyền, HEINEKEN Việt Nam ngày càng chiếm trọn tình cảm người tiêu dùng bởi sự đa dạng, phong phú nhiều loại sản phẩm khác nhau. Đồng thời nhờ sự phổ biến của sản phẩm, HEINEKEN Việt Nam hằng năm đều đóng góp gần 0,9% GDP cho nền kinh tế đất nước. Nhờ nguồn nguyên liệu thiên nhiên, tinh khiết được nhập khẩu từ châu Âu, đồng thời quá trình ủ bia có sử dụng loại men Heineken A-Yeast độc quyền, giúp mỗi ly bia khi được thưởng thức đều sẽ mang màu vàng óng đẹp mắt, mùi thơm lúa mạch dịu nhẹ và hương vị độc đáo, hơi chua chua, ngọt ngọt cũng như vô cùng sảng khoái. Bên cạnh đó, bia Heineken còn gây được sự ấn tượng với thị trường tiêu thụ bởi việc không ngừng đa dạng hóa các dòng sản phẩm khác nhau, cụ thể gần đây nhất chính là sự cho ra đời của bia Heineken 0.0% nồng độ cồn, giúp phù hợp với nhiều độ tuổi, giới tính hơn và đảm bảo về vấn đề sức khỏe.'),
(34, '2024-02-04', 'bongden1.jpg', 'Đèn ngủ gắn tường đế gỗ cao cấp', 26.99, 'BD', 92, 1, 'Đèn ngủ gắn tường đế gỗ cao cấp tiết kiệm điện, ánh sáng ổn định không nhấp nháy, bảo vệ mắt. Tuổi thọ cao, dễ lắp đặt cho phòng khách, phòng ngủ và không gian trang trí.'),
(35, '2025-01-28', 'bongden2.jpg', 'Đèn Tường Da Dê Đẹp Treo Phòng Ngủ Giá Rẻ', 23.99, 'BD', 30, 1, 'Đèn Tường Da Dê Đẹp Treo Phòng Ngủ Giá Rẻ tiết kiệm điện, ánh sáng ổn định không nhấp nháy, bảo vệ mắt. Tuổi thọ cao, dễ lắp đặt cho phòng khách, phòng ngủ và không gian trang trí.'),
