(38, '2024-01-14', 'balo1.jpg', 'Balo Mikkor The Kalino M Light Grey', 54.99, 'BL', 267, 1, 'Balo Mikkor The Kalino M Light Grey thiết kế nhiều ngăn tiện dụng, chất liệu chống thấm nước, quai đeo êm vai. Phù hợp đi học, đi làm và du lịch ngắn ngày.'),
