(47, '2024-02-05', 'laptop1.jpg', 'MacBook Pro 13 inch M1 8GB/256GB', 1204.99, 'LT', 182, 1, 'MacBook Pro 13 inch M1 8GB/256GB cấu hình mạnh mẽ cho học tập, văn phòng và đồ hoạ cơ bản. Thiết kế mỏng nhẹ, bàn phím êm, thời lượng pin dài.'),
