(51, '2026-05-12', 'camera2.jpg', 'Camera IP wifi Ezviz CS-C6N 1080P 2MP', 97.99, 'CMR', 79, 1, 'Camera IP wifi Ezviz CS-C6N 1080P 2MP ghi hình sắc nét, hỗ trợ xem trực tuyến qua điện thoại, cảnh báo chuyển động và đàm thoại hai chiều. Lắp đặt nhanh, bảo hành chính hãng 12 tháng.'),
(52, '2026-03-23', 'raucu5.jpg', 'Cà chua beef hữu cơ - 500g - Chỉ Giao HCM', 1.6, 'RC', 71, 1, 'Cà chua beef hữu cơ - 500g - Chỉ Giao HCM được trồng theo tiêu chuẩn hữu cơ, thu hoạch trong ngày và giao tươi tận nhà. Giàu vitamin, an toàn cho cả gia đình.'),
