(60, '2026-02-04', 'raucu9.jpg', 'Nấm Mỡ Trắng Rica (Khay 200G) - Chỉ Giao HCM', 2.2, 'RC', 100, 1, 'Đây là thực phẩm thích hợp cho những người chán ăn, mệt mỏi do tỳ vị hư yếu, sản phụ thiếu sữa, người viêm phế quản mạn, viêm gan mạn và mắc hội chứng suy giảm bạch cầu. Theo sách Bản thảo cương mục, nấm mỡ có tác dụng ích tràng vị, hóa đàm, lý khí.'),
