(130, '2025-06-24', 'giaydep4.jpg', 'Dép nữ DUWA TNT001S - Quai ngang đế bánh mì', 65.99, 'GD', 176, 1, 'Dép nữ DUWA TNT001S - Quai ngang đế bánh mì đế êm, chống trơn trượt, ôm chân thoải mái khi di chuyển cả ngày. Kiểu dáng trẻ trung, dễ phối đồ.'),
(131, '2025-12-18', 'giaydep5.jpg', 'Giày sneaker nam phong cách thể thao 212', 44.99, 'GD', 20, 1, 'Giày sneaker nam phong cách thể thao 212 đế êm, chống trơn trượt, ôm chân thoải mái khi di chuyển cả ngày. Kiểu dáng trẻ trung, dễ phối đồ.'),
(132, '2026-06-25', 'giaydep6.jpg', 'Dép đúc Thái Lan nữ siêu nhẹ', 32.99, 'GD', 31, 1, 'Dép đúc Thái Lan nữ siêu nhẹ đế êm, chống trơn trượt, ôm chân thoải mái khi di chuyển cả ngày. Kiểu dáng trẻ trung, dễ phối đồ.'),
