(135, '2025-11-21', 'giavi2.jpg', 'Chai nước gia vị cô đặc MAGGI 350g', 4.7, 'GV', 142, 1, 'Chai nước gia vị cô đặc MAGGI 350g được chế biến từ nguyên liệu tự nhiên, đóng gói tiện lợi, giúp món ăn đậm đà chuẩn vị chỉ trong vài phút.'),
(136, '2024-11-04', 'giavi3.jpg', 'Gia vị thịt nướng Toàn Gia 500g/gói', 6.99, 'GV', 252, 1, 'Gia vị thịt nướng Toàn Gia 500g/gói được chế biến từ nguyên liệu tự nhiên, đóng gói tiện lợi, giúp món ăn đậm đà chuẩn vị chỉ trong vài phút.'),
(138, '2026-06-24', 'giavi4.jpg', 'Combo 5 gói Natural Gia vị Ướp Thịt Nướng', 8.99, 'GV', 277, 1, 'Combo 5 gói Natural Gia vị Ướp Thịt Nướng được chế biến từ nguyên liệu tự nhiên, đóng gói tiện lợi, giúp món ăn đậm đà chuẩn vị chỉ trong vài phút.'),
(139, '2025-04-02', 'giavi5.jpg', 'Combo 5 Gói Gia Vị Nấu Phở Vipep - Gia Vị Nấu Phở', 8.99, 'GV', 56, 1, 'Combo 5 Gói Gia Vị Nấu Phở Vipep - Gia Vị Nấu Phở được chế biến từ nguyên liệu tự nhiên, đóng gói tiện lợi, giúp món ăn đậm đà chuẩn vị chỉ trong vài phút.'),
(140, '2024-12-06', 'giavi6.jpg', 'Combo 5 gói Natural Gia vị Ướp Thịt Mắc Mật', 4.8, 'GV', 299, 1, 'Combo 5 gói Natural Gia vị Ướp Thịt Mắc Mật được chế biến từ nguyên liệu tự nhiên, đóng gói tiện lợi, giúp món ăn đậm đà chuẩn vị chỉ trong vài phút.'),
(141, '2025-06-13', 'quanaonu1.jpg', 'Set áo & chân váy thủy thủ nữ', 12.99, 'QAF', 298, 1, 'Set áo & chân váy thủy thủ nữ chất vải mềm mát, form chuẩn tôn dáng, đường may tỉ mỉ. Phù hợp đi chơi, dạo phố và chụp ảnh.'),
(146, '2025-09-19', 'aonam2.jpg', 'Áo thun nam viền đen trắng', 14.99, 'QAM', 118, 1, 'Áo thun nam viền đen trắng chất liệu cotton thoáng khí, thấm hút mồ hôi tốt, form regular dễ mặc. Thích hợp đi làm, đi chơi và thể thao nhẹ.'),
(147, '2025-07-17', 'aopolo.jpg', 'Áo Polo Dry-EX Ngắn Tay', 24.99, 'QAM', 290, 1, 'Áo Polo Dry-EX Ngắn Tay chất liệu cotton thoáng khí, thấm hút mồ hôi tốt, form regular dễ mặc. Thích hợp đi làm, đi chơi và thể thao nhẹ.'),
(150, '2024-08-26', 'hopnhua1.jpg', 'Bộ 3 Hộp Nhựa Đựng Thực Phẩm Song Long Plastic', 7.99, 'H', 286, 1, 'Bộ 3 Hộp Nhựa Đựng Thực Phẩm Song Long Plastic làm từ nhựa nguyên sinh an toàn thực phẩm, nắp kín chống tràn, dùng được trong tủ lạnh và lò vi sóng.'),
